  const rd2=Math.tanh((a2-i2*0.6)*1.8)*0.3;
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(sx*0.08-sy*0.12+t*0.7)*0.3)*1.5)*0.25;
  const reaction=Math.tanh((act-inh*0.7+bg*0.3+spiral+rd2)*2.2);
  const blend=reaction*0.6+cell*0.2+rd2*0.2, v=blend*0.5+0.5;
  const pal=[[5,12,55],[10,45,95],[18,85,125],[25,140,135],[45,175,120],[140,195,85],[210,195,60],[220,155,55],[210,105,65],[185,65,60],[140,40,70],[85,25,65],[45,18,55],[5,12,55]];
  const idx=v*(pal.length-1), i=Math.min(idx|0,pal.length-2), f=idx-i;
  const lum=0.8+Math.sin(reaction*Math.PI)*0.2;
  const edge=Math.abs(reaction)>0.7?1.15:1.0;
  const hi=Math.abs(rd2)>0.25?1.05:1.0;
  const m=lum*edge*hi;
  return[Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*f)*m)|0,Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*f)*m)|0,Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*f)*m)|0];
}
